func newZone() unsafe.Pointer { return unsafe.Pointer(new(geo.Zone)) }

func newNZone(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]geo.Zone, n))) }

func ptrZone(p unsafe.Pointer, c int32) any {
	r := (*geo.Zone)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return &r.Name
	case 4:
		return &r.Center
	case 5:
		return &r.Area
	}
	return nil
}

func valueZone(p unsafe.Pointer, c int32) any {
	r := (*geo.Zone)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return r.Name
	case 4:
		if r.Center == nil {
			return nil
		}
		return r.Center
	case 5:
		if r.Area == nil {
			return nil
		}
		return r.Area
	}
	return nil
}

// PointCol is a column of geo.Point values.
type PointCol struct{ keel.AnyCol }

func (c PointCol) Eq(v geo.Point) keel.Pred             { return c.AnyCol.Eq(&v) }
func (c PointCol) Ne(v geo.Point) keel.Pred             { return c.AnyCol.Ne(&v) }
func (c PointCol) Gt(v geo.Point) keel.Pred             { return c.AnyCol.Gt(&v) }
func (c PointCol) Gte(v geo.Point) keel.Pred            { return c.AnyCol.Gte(&v) }
func (c PointCol) Lt(v geo.Point) keel.Pred             { return c.AnyCol.Lt(&v) }
func (c PointCol) Lte(v geo.Point) keel.Pred            { return c.AnyCol.Lte(&v) }
func (c PointCol) IsDistinctFrom(v geo.Point) keel.Pred { return c.AnyCol.IsDistinctFrom(&v) }
func (c PointCol) Between(lo, hi geo.Point) keel.Pred   { return c.AnyCol.Between(&lo, &hi) }
func (c PointCol) To(v geo.Point) keel.Assignment       { return c.AnyCol.To(&v) }
func (c PointCol) In(vs ...geo.Point) keel.Pred         { return c.AnyCol.In(keel.Pointers(vs)) }
func (c PointCol) NotIn(vs ...geo.Point) keel.Pred      { return c.AnyCol.NotIn(keel.Pointers(vs)) }
